import { clamp } from '../core/math.js';
import { Random } from '../core/rng.js';

// Every sound is generated by oscillators and seeded noise in WebAudio.
export class AudioEngine {
  constructor(noAudio, seed, events) {
    this.disabled = noAudio; this.seed = seed; this.context = null; this.started = false;
    this.volumes = { master: 0.55, music: 0.4, effects: 0.7 }; this.steps = 0;
    events.on('horn', () => this.tone(180, 0.18, 0.15, 'sawtooth'));
    events.on('impact', impact => this.noise(0.12, Math.min(impact / 45, 0.3), 450));
  }
  async start() {
    if (this.disabled) return false;
    try {
      if (!this.context) {
        const AudioContext = window.AudioContext || window.webkitAudioContext; if (!AudioContext) return false;
        this.context = new AudioContext(); const ctx = this.context;
        this.master = ctx.createGain(); this.effects = ctx.createGain(); this.music = ctx.createGain();
        this.effects.connect(this.master); this.music.connect(this.master); this.master.connect(ctx.destination);
        const rng = new Random(this.seed + ':audio');
        this.noiseBuffer = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
        const data = this.noiseBuffer.getChannelData(0); for (let i = 0; i < data.length; i++) data[i] = rng.range(-1, 1);
        this.engine = ctx.createOscillator(); this.engine.type = 'sawtooth'; this.engineGain = ctx.createGain();
        this.filter = ctx.createBiquadFilter(); this.filter.type = 'lowpass'; this.filter.frequency.value = 400;
        this.engine.connect(this.filter); this.filter.connect(this.engineGain); this.engineGain.connect(this.effects); this.engineGain.gain.value = 0; this.engine.start();
        this.siren = ctx.createOscillator(); this.siren.type = 'triangle'; this.sirenGain = ctx.createGain();
        this.siren.connect(this.sirenGain); this.sirenGain.connect(this.effects); this.sirenGain.gain.value = 0; this.siren.start();
        this.wind = ctx.createBufferSource(); this.wind.buffer = this.noiseBuffer; this.wind.loop = true;
        const windFilter = ctx.createBiquadFilter(); windFilter.type = 'lowpass'; windFilter.frequency.value = 180;
        this.windGain = ctx.createGain(); this.windGain.gain.value = 0.035; this.wind.connect(windFilter); windFilter.connect(this.windGain); this.windGain.connect(this.effects); this.wind.start();
        this.applyVolumes();
      }
      await this.context.resume(); this.started = true; return true;
    } catch { return false; }
  }
  applyVolumes(settings = this.volumes) {
    this.volumes = { master: clamp(settings.master ?? 0.55, 0, 1), music: clamp(settings.music ?? 0.4, 0, 1), effects: clamp(settings.effects ?? 0.7, 0, 1) };
    if (!this.context) return;
    for (const name of ['master', 'music', 'effects']) this[name].gain.setTargetAtTime(this.volumes[name], this.context.currentTime, 0.06);
  }
  tone(frequency, duration = 0.1, volume = 0.12, type = 'triangle', when = null, bus = 'effects') {
    if (!this.started || this.context?.state !== 'running') return;
    const ctx = this.context, time = when ?? ctx.currentTime, oscillator = ctx.createOscillator(), gain = ctx.createGain();
    oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, time); oscillator.frequency.exponentialRampToValueAtTime(Math.max(25, frequency * 0.8), time + duration);
    gain.gain.setValueAtTime(0, time); gain.gain.linearRampToValueAtTime(volume, time + 0.006); gain.gain.exponentialRampToValueAtTime(0.001, time + duration);
    oscillator.connect(gain); gain.connect(this[bus]); oscillator.start(time); oscillator.stop(time + duration + 0.02);
    oscillator.onended = () => { oscillator.disconnect(); gain.disconnect(); };
  }
  noise(duration = 0.1, volume = 0.15, frequency = 1000, when = null, bus = 'effects') {
    if (!this.started || this.context?.state !== 'running') return;
    const ctx = this.context, time = when ?? ctx.currentTime, source = ctx.createBufferSource(), filter = ctx.createBiquadFilter(), gain = ctx.createGain();
    source.buffer = this.noiseBuffer; filter.type = 'lowpass'; filter.frequency.value = frequency;
    gain.gain.setValueAtTime(volume, time); gain.gain.exponentialRampToValueAtTime(0.001, time + duration);
    source.connect(filter); filter.connect(gain); gain.connect(this[bus]); source.start(time); source.stop(time + duration);
    source.onended = () => { source.disconnect(); filter.disconnect(); gain.disconnect(); };
  }
  update(dt, game) {
    if (!this.started || this.context.state !== 'running') return;
    const ctx = this.context, car = game.player.vehicle;
    this.engine.frequency.setTargetAtTime(car ? 35 + car.rpm * 0.012 : 35, ctx.currentTime, 0.045);
    this.filter.frequency.setTargetAtTime(car ? 180 + car.rpm * 0.15 : 180, ctx.currentTime, 0.05);
    this.engineGain.gain.setTargetAtTime(car ? 0.06 + Math.abs(car.speed) * 0.0016 : 0, ctx.currentTime, 0.1);
    this.siren.frequency.setTargetAtTime(520 + (Math.sin(game.time * 4) + 1) * 280, ctx.currentTime, 0.06);
    this.sirenGain.gain.setTargetAtTime(game.wanted?.stars > 0 ? 0.045 : 0, ctx.currentTime, 0.15);
    this.steps += dt * game.player.speed;
    if (!car && game.player.grounded && this.steps > 1.6) { this.steps = 0; this.noise(0.045, 0.09, 250); }
    if (car && Math.abs(car.steering * car.speed) > 4 && Math.sin(game.time * 20) > 0.9) this.tone(800, 0.04, 0.025, 'sawtooth');
  }
  pause(paused) {
    if (!this.context || this.disabled) return;
    try { const promise = paused ? this.context.suspend() : this.context.resume(); promise?.catch?.(() => {}); } catch { /* Audio can be unavailable. */ }
  }
}
